import {ROUTES, validate, poolFor, searchChampions, randomChampion} from './core.js';
import {configured,loadShared,isAdmin,signIn,signOut,watchAuth,prepareImage,saveChampion,getClient} from './shared.js';
import {mergeOverrides} from './shared-core.js';
const $=s=>document.querySelector(s);
let base=[],champions=[],drawRoute='Todos',listRoute='Todos',busy=false,admin=false,loading=false,selected=null,lastDraw=null,editImage=null,removeImage=false,previewUrl=null,saving=false,preparing=false,imageSequence=0,remoteReady=false;
const icons={Todos:'✦',TOP:'◩',JUNGLE:'♧',MID:'◇',ADC:'◎',SUPPORT:'♜'};
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n;}
function badges(c){const box=el('div','badges');c.rotas.forEach(r=>box.append(el('span','badge',r)));return box;}
function portrait(c,cls=''){
 const wrap=el('div',`portrait ${cls}`),fallback=el('span','initial',c.nome.slice(0,2).toUpperCase());wrap.append(fallback);
 if(c.imagem){const img=el('img');img.alt=c.nome;img.loading=cls==='large'||cls==='detail-image'?'eager':'lazy';img.onload=()=>{fallback.hidden=true;};img.onerror=()=>{img.remove();fallback.hidden=false;};img.src=c.imagem;wrap.append(img);}return wrap;
}
function externalLink(c,cls='build-link'){const a=el('a',cls,'Ver counters e builds ↗');a.href=c.link;a.target='_blank';a.rel='noopener noreferrer';return a;}
function routes(target,selectedRoute,callback,counts){const root=$(target);root.replaceChildren();['Todos',...ROUTES].forEach(r=>{const b=el('button',r===selectedRoute?'route active':'route');b.type='button';b.setAttribute('aria-pressed',String(r===selectedRoute));b.disabled=target==='#draw-routes'&&busy;if(counts)b.append(el('span','route-icon',icons[r]));b.append(el('span','',r));if(counts)b.append(el('small','',String(poolFor(champions,r).length)));b.onclick=()=>callback(r);root.append(b);});}
function renderDrawRoutes(){routes('#draw-routes',drawRoute,r=>{drawRoute=r;renderDrawRoutes();},true);const count=poolFor(champions,drawRoute).length;$('#pool-count').textContent=count;$('#draw').disabled=busy||count===0;$('#draw').textContent=busy?'Sorteando…':count?'⇄ Sortear campeão':'Nenhum campeão nesta rota';}
function renderList(){routes('#list-routes',listRoute,r=>{listRoute=r;renderList();},false);const matches=searchChampions(champions,listRoute,$('#search').value);$('#list-count').textContent=matches.length;const root=$('#champions');root.replaceChildren();matches.forEach(c=>{const button=el('button','champion');button.type='button';button.setAttribute('aria-label',`Abrir ficha de ${c.nome}`);button.append(portrait(c));const info=el('div','champion-info');info.append(el('h3','',c.nome),badges(c));button.append(info,el('span','external','＋'));button.onclick=()=>openChampion(c.id);root.append(button);});if(!matches.length){const empty=el('div','no-results');empty.append(el('h3','','Nenhum campeão encontrado'),el('p','','Tente outro nome ou altere a rota.'));root.append(empty);}}
function showResult(c,route){lastDraw={id:c.id,route};const root=$('#result');root.replaceChildren();root.classList.add('revealed');root.append(portrait(c,'large'));const info=el('div','result-info');info.append(el('p','eyebrow',`SEU CAMPEÃO · ${route.toUpperCase()}`),el('h2','',c.nome),badges(c));const actions=el('div','result-actions'),details=el('button','build-link','Abrir ficha');details.type='button';details.onclick=()=>openChampion(c.id);actions.append(externalLink(c),details);info.append(actions);root.append(info);}
function render(){renderDrawRoutes();renderList();if(lastDraw){const c=champions.find(x=>x.id===lastDraw.id);if(c)showResult(c,lastDraw.route);}}
$('#draw').onclick=async()=>{if(busy||!poolFor(champions,drawRoute).length)return;busy=true;const route=drawRoute,chosen=randomChampion(poolFor(champions,route));renderDrawRoutes();await new Promise(r=>setTimeout(r,matchMedia('(prefers-reduced-motion: reduce)').matches?0:420));showResult(chosen,route);busy=false;renderDrawRoutes();};
$('#search').addEventListener('input',renderList);
async function sync(){if(loading||!base.length)return;loading=true;try{const next=await loadShared(base);remoteReady=configured;if(JSON.stringify(next)!==JSON.stringify(champions)){champions=next;render();}$('#status').textContent='';}catch{$('#status').textContent=champions.length?'Sem conexão com as alterações compartilhadas. Exibindo a última lista carregada.':'Não foi possível carregar as alterações compartilhadas.';remoteReady=false;}finally{loading=false;}}
async function load(){try{const response=await fetch('./campeoes_wild_rift_141.json');if(!response.ok)throw Error();base=validate(await response.json());champions=mergeOverrides(base,[],()=> '');render();await sync();}catch{$('#status').textContent='Não foi possível carregar os campeões. ';const retry=el('button','','Tentar novamente');retry.onclick=load;$('#status').append(retry);}}
function resetPreview(){imageSequence++;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=null;editImage=null;removeImage=false;preparing=false;}
function updatePermissions(){const enabled=admin&&configured;$('#editor-fields').disabled=!enabled||saving;$('#save-champion').hidden=!enabled;$('#edit-help').textContent=enabled?'As alterações serão publicadas para todos os visitantes.':'Entre como administrador para alterar as rotas e a imagem.';$('#detail-login').hidden=enabled;$('#admin-button').textContent=admin?'Sair da administração':'Administrar';$('#admin-badge').hidden=!admin;}
function drawPreview(image){$('#detail-preview').replaceChildren(portrait({...selected,imagem:image},'detail-image'));}
function openChampion(id){const c=champions.find(x=>x.id===id);if(!c)return;selected={...c,rotas:[...c.rotas]};resetPreview();$('#image-file').value='';$('#edit-status').textContent='';$('#detail-title').textContent=c.nome;$('#detail-link').replaceChildren(externalLink(c));drawPreview(c.imagem);const group=$('#edit-routes');group.replaceChildren();ROUTES.forEach(r=>{const label=el('label','route-choice');const input=el('input');input.type='checkbox';input.name='rotas';input.value=r;input.checked=c.rotas.includes(r);label.append(input,el('span','',r));group.append(label);});updatePermissions();$('#champion-dialog').showModal();}
$('#champion-dialog').addEventListener('close',resetPreview);
$('#champion-dialog').addEventListener('cancel',event=>{if(saving)event.preventDefault();});
$('#close-detail').onclick=()=>{if(!saving)$('#champion-dialog').close();};
$('#remove-image').onclick=()=>{resetPreview();removeImage=true;$('#image-file').value='';drawPreview('');$('#edit-status').textContent='A imagem será removida ao salvar.';$('#save-champion').disabled=false;};
$('#image-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;const sequence=++imageSequence;preparing=true;$('#save-champion').disabled=true;$('#edit-status').textContent='Preparando imagem…';try{const blob=await prepareImage(file);if(sequence!==imageSequence)return;if(previewUrl)URL.revokeObjectURL(previewUrl);editImage=blob;removeImage=false;previewUrl=URL.createObjectURL(blob);drawPreview(previewUrl);$('#edit-status').textContent='Imagem pronta. Clique em salvar para publicar.';}catch(error){if(sequence===imageSequence){$('#edit-status').textContent=error.message;$('#image-file').value='';}}finally{if(sequence===imageSequence){preparing=false;$('#save-champion').disabled=false;}}};
$('#edit-form').onsubmit=async event=>{event.preventDefault();if(saving||preparing||!admin||!selected)return;const rotas=[...$('#edit-routes').querySelectorAll('input:checked')].map(n=>n.value);if(!rotas.length){$('#edit-status').textContent='Selecione pelo menos uma rota.';return;}if(!remoteReady){await sync();if(!remoteReady){$('#edit-status').textContent='Sem conexão para salvar. Tente novamente quando a conexão voltar.';return;}}
 saving=true;$('#save-champion').disabled=true;$('#close-detail').disabled=true;updatePermissions();$('#edit-status').textContent=editImage?'Enviando imagem e salvando…':'Salvando alterações…';try{const row=await saveChampion({champion:selected,rotas,imageBlob:editImage,removeImage});const client=await getClient();const saved=mergeOverrides(base,[row],path=>client.storage.from('wr-champion-images').getPublicUrl(path).data.publicUrl).find(c=>c.id===selected.id);champions=champions.map(c=>c.id===saved.id?saved:c);selected=saved;resetPreview();$('#image-file').value='';drawPreview(saved.imagem);render();$('#edit-status').textContent='Salvo! As alterações já estão disponíveis para todos.';}catch(error){$('#edit-status').textContent=error.message;await sync();}finally{saving=false;$('#save-champion').disabled=false;$('#close-detail').disabled=false;updatePermissions();}};
function openLogin(){if(!configured){$('#login-status').textContent='A administração ainda não foi configurada. Consulte as instruções de instalação do projeto.';$('#login-fields').disabled=true;}else{$('#login-status').textContent='';$('#login-fields').disabled=false;}$('#login-dialog').showModal();}
$('#close-login').onclick=()=>$('#login-dialog').close();$('#detail-login').onclick=openLogin;
$('#admin-button').onclick=async()=>{if(!admin){openLogin();return;}try{await signOut();admin=false;updatePermissions();}catch(error){$('#status').textContent=error.message;}};
$('#login-form').onsubmit=async event=>{event.preventDefault();$('#login-fields').disabled=true;$('#login-status').textContent='Entrando…';try{await signIn($('#admin-email').value,$('#admin-password').value);admin=true;updatePermissions();$('#login-dialog').close();$('#admin-password').value='';await sync();}catch(error){$('#login-status').textContent=error.message;$('#admin-password').value='';}finally{$('#login-fields').disabled=false;}};
async function refreshAuth(){try{admin=await isAdmin();}catch{admin=false;}updatePermissions();}
load();if(configured){refreshAuth();watchAuth(refreshAuth).catch(()=>{});setInterval(()=>{if(!document.hidden)sync();},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){sync();refreshAuth();}});window.addEventListener('online',sync);}updatePermissions();
